    n = len(my_matrix)
    if n == 0:
        return False

    # Calculate the sum of the first row to use as a reference
    magic_sum = sum(my_matrix[0])

    # Check rows and columns
    for i in range(n):
        if sum(my_matrix[i]) != magic_sum or sum([my_matrix[j][i] for j in range(n)]) != magic_sum:
            return False

    # Check diagonals
    if sum([my_matrix[i][i] for i in range(n)]) != magic_sum or sum([my_matrix[i][n-i-1] for i in range(n)]) != magic_sum:
        return False

    return True

from typing import Optional

def find_solution(a: int, b: int, n: int) -> Optional[tuple]:
    # Check if a and b are coprime
    if gcd(a, b) != 1:
        return None

    # Extended Euclidean algorithm to find x and y
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        x = y1
        y = x1 - (x // y) * y1
        return gcd, x, y

    gcd, x, y = extended_gcd(a, b)

    # If gcd is not 1, no solution exists
    if gcd != 1:
        return None

    # Scale the solution to match the equation ax + by = n
    k = n // gcd
    return (k * x, k * y)

