def is_sublist(l, s):
    # Check if the sublist is empty
    if not s:
        return True

    # Iterate over the list l
    for i in range(len(l) - len(s) + 1):
        # Check if the current slice of l matches the sublist s
        if l[i:i+len(s)] == s:
            return True

    # If no match is found, return False
    return False

