def is_samepatterns(colors, patterns):
    # Check if the number of colors matches the number of patterns
    if len(colors) != len(patterns):
        return False

    # Iterate over each color and pattern pair
    for color, pattern in zip(colors, patterns):
        # Check if the color matches the pattern
        if color != pattern:
            return False

    # If all checks pass, the sequences match
    return True

def tuple_to_dict(test_tup):
    # Check if the length of the tuple is even
    if len(test_tup) % 2 != 0:
        raise ValueError("Tuple must have an even number of elements.")

    # Create a dictionary from adjacent elements in the tuple
    result_dict = dict(zip(test_tup[::2], test_tup[1::2]))

    return result_dict

