def divisible_by_digits(startnum, endnum):
    def is_divisible_by_digits(n):
        digits = set(str(n))
        if '0' in digits:  # If the number contains '0', it cannot be divisible by 0
            return False
        for digit in digits:
            if n % int(digit) != 0:
                return False
        return True

    result = [n for n in range(startnum, endnum + 1) if is_divisible_by_digits(n)]
    return result

