def is_undulating(n):
    # Convert the number to a string to easily iterate over digits
    str_n = str(n)

    # Check if the number has less than 3 digits, which cannot be undulating
    if len(str_n) < 3:
        return False

    # Check if the first two digits are the same
    if str_n[0] == str_n[1]:
        # Check if the rest of the digits alternate between the first two
        for i in range(2, len(str_n)):
            if (str_n[i] != str_n[i - 2]) or (str_n[i] == str_n[i - 2]):
                return False
        return True

    # Check if the first digit is the same as the third digit
    if str_n[0] == str_n[2]:
        # Check if the rest of the digits alternate between the first and third
        for i in range(3, len(str_n)):
            if (str_n[i] != str_n[i - 2]) or (str_n[i] == str_n[i - 2]):
                return False
        return True

    # If none of the above conditions are met, the number is not undulating
    return False

