from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Count the occurrences of each letter
    letter_counts = Counter(test.split())

    # Find the maximum occurrence count
    max_count = max(letter_counts.values())

    # Collect all letters that have the maximum occurrence count
    result = {letter: count for letter, count in letter_counts.items() if count == max_count}

    return result

from collections import Counter

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Count the total number of opening and closing parentheses
    total_open = sum(Counter(lst[0]).values())
    total_close = sum(Counter(lst[1]).values())

    # Check if the total number of opening and closing parentheses are equal
    if total_open != total_close:
        return 'No'

    # Check if either string is already balanced
    if is_balanced(lst[0]) or is_balanced(lst[1]):
        return 'Yes'

    # Try concatenating in both possible orders
    if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]):
        return 'Yes'

    return 'No'

